input.code:
const ci = await $`ls .github/workflows; cat .github/workflows/*.yml`.nothrow().text();
const list = await $`cargo test --tests -- --list --format terse 2>/dev/null`.text();
const times = [];
for (const t of ['broadband_test','noisy_data_test','ifb_test','integration_test']) {
  const names = (await $`cargo test --test ${t} -- --list --format terse 2>/dev/null`.text()).split('\n').filter(l=>l.endsWith(': test')).map(l=>l.replace(': test',''));
  for (const n of names) { const s=Date.now(); await $`cargo test -q --test ${t} -- --exact ${n}`.nothrow().quiet(); times.push([t,n,(Date.now()-s)/1000]); }
}
({ci, times})

