const slowTests = {
  'tests/broadband_test.rs': ['test_broadband_single_source_doa_frequency_triples'],
  'tests/noisy_data_test.rs': ['test_single_source_doa_noisy_10db','test_single_source_doa_noisy_5db','test_single_source_doa_noisy_1db'],
  'tests/integration_test.rs': ['test_single_source_doa'],
};
for (const [f, names] of Object.entries(slowTests))
  await edit(f, names.map(n => [`#[test]\nfn ${n}(`, `#[test]\n#[ignore = "slow"]\nfn ${n}(`]));

// hook: drop skip list, rely on #[ignore]
let h = await file('.claude/hooks/run-tests.sh').text();
h = h.replace(/# Skipping:[\s\S]*?entirely\.\n/, `# Skipping:
#   - Slow tests carry #[ignore = "slow"]; plain \`cargo test\` (what this hook
#     runs) skips them. Run them with \`cargo test -- --include-ignored\`.
#   - MUSICRS_SKIP_HOOK_TESTS=1 in the environment Claude Code was started
#     from disables the hook entirely.
`);
h = h.replace(/skip_args=\(\)[\s\S]*?skip_args=\(--exact "\$\{skip_args\[@\]\}"\)\n\n/, '');
h = h.replace('cargo test --quiet -- "${skip_args[@]}"', 'cargo test --quiet');
h = h.replace('(slow tests in $slow_list skipped)', '(slow #[ignore] tests skipped)');
await write('.claude/hooks/run-tests.sh', h);
await $`git rm -q .claude/hooks/slow-tests.txt`;

await edit('.github/workflows/ci.yml', '--profile ci \\\n', '--profile ci \\\n            --run-ignored all \\\n');

await edit('CLAUDE.md', [
  ["cargo test              # all tests (unit + integration)\n", "cargo test              # all tests except slow ones (#[ignore = \"slow\"])\ncargo test -- --include-ignored   # full suite, including slow tests (CI runs this)\n"],
  [/- A project Stop hook.*\n/.exec(await file('CLAUDE.md').text())[0],
   "- A project Stop hook (`.claude/settings.json` → `.claude/hooks/run-tests.sh`) runs `cargo test` when a turn ends with changed code under `src/`, `tests/` or `Cargo.*`, and sends failures back to Claude. Tests that take more than ~10 s are marked `#[ignore = \"slow\"]`, so the hook skips them; run `cargo test -- --include-ignored` for the full suite. Set `MUSICRS_SKIP_HOOK_TESTS=1` before starting Claude Code to turn the hook off.\n"],
]);
const [h2, grepLeft] = [await file('.claude/hooks/run-tests.sh').text(), await $`grep -rn "slow-tests\\|skip_args" . --exclude-dir=target --exclude-dir=.git`.nothrow().text()];
const checks = await $`cargo fmt --check && cargo clippy -q --all-targets -- -D warnings && bash -n .claude/hooks/run-tests.sh && echo OK`.nothrow();
const env = {CLAUDE_PROJECT_DIR: '/home/orchid/projects/musicrs'};
let s=Date.now(); const hk = await $`echo '{}' | .claude/hooks/run-tests.sh`.env(env).nothrow(); const th=(Date.now()-s)/1000;
const ign = await $`grep "test result" target/.claude-hook/last-run.log`.nothrow().text();
const nx = await $`cargo nextest --version`.nothrow();
({grepLeft, checks: checks.output, hook:[hk.exitCode, th, hk.output], ign, nx: nx.exitCode})

const full = await $`cargo test -q -- --include-ignored 2>&1 | grep "test result"`.nothrow();
let committed = 'not committed';
if (!/FAILED/.test(full.stdout) && full.stdout.includes('3 passed')) {
  await $`git add -A tests .claude .github CLAUDE.md && git commit -q -m ${'Mark slow tests #[ignore = "slow"] instead of a hook skip list\n\nUses the standard libtest mechanism: plain `cargo test` (and the Stop\nhook) skip the five tests that take more than ~10 s; CI runs them via\nnextest --run-ignored all, locally `cargo test -- --include-ignored`.\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>'}`;
  committed = await $`git log --oneline -1 --stat`.text();
}
({full: full.stdout, committed})

