input.code:
const full = await $`cargo test -q -- --include-ignored 2>&1 | grep "test result"`.nothrow();
let committed = 'not committed';
if (!/FAILED/.test(full.stdout) && full.stdout.includes('3 passed')) {
  await $`git add -A tests .claude .github CLAUDE.md && git commit -q -m ${'Mark slow tests #[ignore = "slow"] instead of a hook skip list\n\nUses the standard libtest mechanism: plain `cargo test` (and the Stop\nhook) skip the five tests that take more than ~10 s; CI runs them via\nnextest --run-ignored all, locally `cargo test -- --include-ignored`.\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>'}`;
  committed = await $`git log --oneline -1 --stat`.text();
}
({full: full.stdout, committed})

